mapper.insert:
INSERT INTO chapters (
    course_id, parent_id, title, chapter_index, chapter_type, content_type, sort
) VALUES (
    #{courseId}, #{parentId}, #{title}, #{chapterIndex}, #{chapterType}, #{contentType}, #{sort}
)

mapper.update:
UPDATE chapters
title = #{title}, chapter_index = #{chapterIndex}, content_type = #{contentType}, sort = #{sort},
WHERE chapter_id = #{chapterId}

mapper.select:
SELECT chapter_id, course_id, parent_id, title, chapter_index, chapter_type, content_type, sort, create_time, update_time
FROM chapters
WHERE chapter_id = #{chapterId}
